def svg(name, size=None, cls=''):
    s = f' width="{size}" height="{size}"' if size else ''
    c = f' class="{cls}"' if cls else ''
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"{s}{c} aria-hidden="true">{ICONS[name]}</svg>'
if __name__ == '__main__':
    import sys, os
    d = sys.argv[1]; os.makedirs(d, exist_ok=True)
    for n in ICONS: open(os.path.join(d, n + '.svg'), 'w').write(svg(n, 24) + '\n')
    print(len(ICONS), 'icônes')
